INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 16, 'theory', 'Квиз: CSS — селекторы, состояния и специфичность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 0, 'Что сделает браузер, если в одном объявлении правила опечатка в имени свойства?', '["Отбросит всё правило целиком","Отбросит только это объявление, остальные продолжат работать","Остановит отрисовку и покажет сообщение об ошибке","Проигнорирует весь файл со стилями"]', 1, 'Разбор CSS прощает ошибки: недопустимое объявление молча отбрасывается, соседние работают. Сломанный селектор хуже: он убивает правило целиком. Поэтому «ничего не изменилось» — повод заглянуть в инструменты разработчика.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 1, 'Что выбирает селектор .menu > li?', '["Только пункты li, которые являются прямыми детьми элемента с классом menu","Все пункты li на любой глубине внутри .menu","Пункты li, стоящие сразу после .menu","Элементы .menu, внутри которых есть li"]', 0, 'Знак «больше» — прямой ребёнок. Для любой глубины используют пробел, для следующего соседа — плюс, а выбор по содержимому — это :has.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 2, 'Какое правило победит: «#nav a» или «.menu .item a.link»?', '["Второе: в нём больше классов","Победит то, что записано ниже в файле","Они равны, потому что в обоих есть тип a","Первое: один идентификатор тяжелее любого числа классов"]', 3, 'Специфичность — тройка (идентификаторы, классы, типы), её сравнивают слева направо: у первого селектора (1, 0, 1), у второго (0, 3, 1). Порядок в файле решает только при полном равенстве.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 3, 'Чем :where() отличается от :is()?', '["Только :where принимает несколько селекторов","Только :is работает с классами","Специфичность :where всегда нулевая, а :is берёт самый тяжёлый аргумент","Они ничем не отличаются"]', 2, 'Совпадают элементы одни и те же, но вес разный. Нулевая специфичность :where удобна для базовых стилей, которые легко переопределить любым правилом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 4, 'Для чего подходят ::before и ::after со свойством content?', '["Для важного текста, который обязан прочитать скринридер","Для украшений: стрелок, значков, подчёркиваний","Для содержимого, по которому будет искать поисковик","Вместо настоящих элементов разметки, например кнопок"]', 1, 'Содержимое из CSS не входит в разметку: его могут не прочитать, не найти и не выделить. Смысл должен жить в HTML, а псевдоэлементы остаются оформлением.');
